<?php $currentPage=$currentPage??'';if(!isset($user)||!is_array($user))$user=current_user();$f=trim((string)($user['first_name']??''));$l=trim((string)($user['last_name']??''));$name=trim((string)($user['full_name']??$user['fullname']??($f.' '.$l)));if($name==='')$name='Commercial Manager';$initials=cm_initials($f,$l);$titles=['dashboard'=>'Dashboard','saved_searches'=>'Saved Searches','capability_packs'=>'Capability Packs','privacy_rules'=>'Privacy Rules','reports'=>'Reports','activity_log'=>'Activity Log','saved_search_view'=>'Saved Searches','generate_pack'=>'Capability Packs','pack_view'=>'Capability Packs'];$title=$titles[$currentPage]??'Commercial Manager Portal';$uid=(int)($user['id']??$user['user_id']??0);$nd=cm_notifications($conn,$uid,6);$notifications=$nd['items'];$unread=(int)$nd['unread'];?><header class="ux-navbar"><div class="ux-navbar__left"><button class="ux-navbar__menu" id="uxMenuButton"><i class="fas fa-bars"></i></button><div class="ux-navbar__heading"><span>Commercial Manager Workspace</span><h1><?=e($title)?></h1></div></div><div class="ux-navbar__right"><button class="ux-theme-toggle" data-ux-theme-toggle title="Toggle dark mode"><i class="fas fa-moon" data-ux-theme-icon></i></button><div class="ux-navbar__notification"><button class="ux-navbar__icon-button ux-notification-button" id="uxNotificationButton"><i class="fas fa-bell"></i><?php if($unread>0):?><span class="ux-notification-badge"><?=$unread>99?'99+':$unread?></span><?php endif;?></button><div class="ux-dropdown" id="uxNotificationDropdown"><div class="ux-dropdown__head"><strong>Notifications</strong><span><?=$unread?> unread</span></div><div class="ux-dropdown__body"><?php if(!$notifications):?><div class="ux-empty ux-empty--compact"><div class="ux-empty__icon"><i class="fas fa-bell"></i></div><strong>You're all caught up</strong><span>No notifications to display.</span></div><?php else:foreach($notifications as $n):?><div class="ux-notification-item <?=(int)($n['is_read']??1)===0?'